import SwiftUI struct ConfirmEmailView: View { let email: String let onConfirmed: () -> Void @StateObject private var auth = AuthService.shared @State private var code = "" @State private var error: String? = nil @State private var loading = false @State private var resent = false var body: some View { NavigationStack { VStack(spacing: 24) { Image(systemName: "envelope.badge.fill") .font(.system(size: 56)) .foregroundColor(.blue) .padding(.top, 32) Text("Check Your Email") .font(.largeTitle.bold()) Text("We sent a 6-digit code to\n**\(email)**") .multilineTextAlignment(.center) .foregroundColor(.secondary) TextField("Enter 6-digit code", text: $code) .textFieldStyle(.roundedBorder) .keyboardType(.numberPad) .font(.title2.monospacedDigit()) .multilineTextAlignment(.center) .padding(.horizontal) if let error = error { Text(error).font(.caption).foregroundColor(.red) } if resent { Text("Code resent!").font(.caption).foregroundColor(.green) } Button(action: confirm) { if loading { ProgressView().frame(maxWidth: .infinity) } else { Text("Verify Email").frame(maxWidth: .infinity) } } .buttonStyle(.borderedProminent) .disabled(code.count < 6 || loading) .padding(.horizontal) Button("Resend Code") { resend() } .font(.caption) .foregroundColor(.blue) Spacer() } .navigationTitle("Verify Email") .navigationBarTitleDisplayMode(.inline) } } func confirm() { loading = true; error = nil Task { do { try await auth.confirmSignUp(email: email, code: code) onConfirmed() } catch { self.error = error.localizedDescription } loading = false } } func resend() { Task { do { try await auth.resendConfirmationCode(email: email) resent = true } catch { error = error.localizedDescription } } } }
